class DjangoModuleProgramName(AdminScriptTestCase):
    def test_help(self):
        for args in ([], ['help'], ['--help'], ['-h']):
            with self.subTest(args=args):
                out, err = self.run_test('-m', ['django'] + args)
                self.assertNoOutput(err)
                self.assertOutput(
                    out,
                    "Type 'python -m django help <subcommand>' for help on a specific subcommand.",
                )
                self.assertNotInOutput(out, '__main__.py')

    def test_command_help(self):
        for args in (['help', 'check'], ['check', '--help']):
            with self.subTest(args=args):
                out, err = self.run_test('-m', ['django'] + args)
                self.assertNoOutput(err)
                self.assertOutput(out, 'usage: python -m django check')
                self.assertNotInOutput(out, '__main__.py')

    def test_unknown_command(self):
        out, err = self.run_test('-m', ['django', 'nonexistent'])
        self.assertNoOutput(out)
        self.assertOutput(err, "Unknown command: 'nonexistent'")
        self.assertOutput(err, "Type 'python -m django help' for usage.")

    def test_command_parser_error(self):
        out, err = self.run_test('-m', ['django', 'check', '--nonexistent'])
        self.assertNoOutput(out)
        self.assertOutput(err, 'usage: python -m django check')
        self.assertOutput(err, 'python -m django check: error: unrecognized arguments: --nonexistent')
        self.assertNotInOutput(err, '__main__.py')


